	for i := 0; i <= 4; i++ {
		q := queue("a", "b", "c", "d")
		q.Insert(i, Track{Title: "NEW"})
		want := append(append(append([]string{}, []string{"a", "b", "c", "d"}[:i]...), "NEW"), []string{"a", "b", "c", "d"}[i:]...)
		if got := q.Titles(); !reflect.DeepEqual(got, want) {
