		t.Errorf("the input was modified: %v", in)
	}
	got[0] = 42
	if in[0] != 3 {
		t.Errorf("the result shares memory with the input")
	}
	if got := Dedup(nil); len(got) != 0 {
		t.Errorf("nil: %v", got)
	}
}

